output_text:
[
  {
    "id": "return_cart_to_bay",
    "text": "A shopper who enters the store is obliged to return the cart to the designated return bay at (0,1) before leaving.",
    "abstraction": {
      "state_properties": {
        "return_bay": "at(0,1)",
        "cart_at_return_bay": "cartAt(0,1)",
        "holding_cart": "hasCart"
      },
      "events": {
        "return_cart_to_bay": {
          "pre": {
            "and": [
              "holding_cart",
              "return_bay",
              "LEAVE_CART"
            ]
          },
          "post": "cart_at_return_bay"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "return_cart_to_bay"
    }
  },
  {
    "id": "exit_only_after_cart_parked",
    "text": "It is forbidden to exit the supermarket unless the cart has been parked at the return bay.",
    "abstraction": {
      "state_properties": {
        "cart_at_return_bay": "cartAt(0,1)"
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "EXIT",
          {
            "not": "cart_at_return_bay"
          }
        ]
      }
    }
  },
  {
    "id": "no_exit_with_cart",
    "text": "It is forbidden for a shopper to leave the store while still holding or pushing a cart.",
    "abstraction": {
      "state_properties": {
        "holding_cart": "hasCart"
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "EXIT",
          "holding_cart"
        ]
      }
    }
  },
  {
    "id": "cart_pickup_at_entrance_required",
    "text": "A shopper is obliged to collect the entrance cart before doing the shopping.",
    "abstraction": {
      "state_properties": {
        "entrance_cart_station": {
          "and": [
            "at(1,5)",
            "cartAt(1,5)"
          ]
        },
        "holding_cart": "hasCart"
      },
      "events": {
        "pickup_entrance_cart": {
          "pre": {
            "and": [
              "entrance_cart_station",
              "PICKUP_CART"
            ]
          },
          "post": "holding_cart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "pickup_entrance_cart"
    }
  },
  {
    "id": "items_must_be_collected_with_cart",
    "text": "It is forbidden to pick up shelf items unless the shopper is currently holding the cart.",
    "abstraction": {
      "state_properties": {
        "holding_cart": "hasCart"
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "PICKUP_ITEM",
          {
            "not": "holding_cart"
          }
        ]
      }
    }
  },
  {
    "id": "no_hand_carrying",
    "text": "It is forbidden to carry merchandise by hand rather than placing it in the cart.",
    "abstraction": {
      "state_properties": {
        "carrying_by_hand": "handFull",
        "holding_cart": "hasCart"
      },
      "events": {
        "pickup_item_into_hand": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              {
                "not": "holding_cart"
              }
            ]
          },
          "post": "carrying_by_hand"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "or": [
          "carrying_by_hand",
          "pickup_item_into_hand"
        ]
      }
    }
  },
  {
    "id": "return_cart_after_item_pickup",
    "text": "After any item is collected using the cart, the shopper is obliged eventually to return that cart to the return bay.",
    "abstraction": {
      "state_properties": {
        "holding_cart": "hasCart",
        "return_bay": "at(0,1)",
        "cart_at_return_bay": "cartAt(0,1)"
      },
      "events": {
        "cart_item_pickup": {
          "pre": {
            "and": [
              "holding_cart",
              "PICKUP_ITEM"
            ]
          },
          "post": null
        },
        "return_cart_to_bay": {
          "pre": {
            "and": [
              "holding_cart",
              "return_bay",
              "LEAVE_CART"
            ]
          },
          "post": "cart_at_return_bay"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "cart_item_pickup",
      "discharge": "return_cart_to_bay"
    }
  },
  {
    "id": "no_abandoned_cart_outside_stations",
    "text": "It is forbidden to be separated from a cart unless the cart is at the entrance station or the return bay.",
    "abstraction": {
      "state_properties": {
        "holding_cart": "hasCart",
        "cart_at_entrance_station": "cartAt(1,5)",
        "cart_at_return_bay": "cartAt(0,1)",
        "cart_at_allowed_station": {
          "or": [
            "cart_at_entrance_station",
            "cart_at_return_bay"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          {
            "not": "holding_cart"
          },
          {
            "not": "cart_at_allowed_station"
          }
        ]
      }
    }
  }
]
